SELECT Country, COUNT(DISTINCT Singer_ID) AS Number_of_Singers
FROM singer
GROUP BY Country;

SELECT T1.Name AS Stadium_Name, T1.Capacity FROM stadium AS T1 JOIN (
    SELECT Stadium_ID, AVG(Average) AS Avg_Avg FROM stadium GROUP BY Stadium_ID ORDER BY Avg_Avg DESC LIMIT 1
) AS T2 ON T1.Stadium_ID = T2.Stadium_ID;


